property.value:
let $sorted := function($call) {
      $call/*[1][self::MethodCall[@MethodName = 'sorted'][*[1][pmd-java:typeIs('java.util.stream.Stream')]]]
    },
    $listed := function($call) {
      $call/*[1][self::MethodCall[@MethodName = 'toList' and ArgumentList/@Size = 0
                                  or @MethodName = 'collect' and ArgumentList/@Size = 1]][exists($sorted(.))]
    }
return //MethodCall[@MethodName = 'findFirst'][ArgumentList/@Size = 0][exists($sorted(.))]
  | //MethodCall[@MethodName = 'get'][ArgumentList[@Size = 1]/NumericLiteral[@ValueAsInt = 0]][exists($listed(.))]
  | //MethodCall[@MethodName = ('getFirst', 'getLast')][ArgumentList/@Size = 0][exists($listed(.))]
